"""Timed auto-close for the bounded key sequences generated by this project."""
import math
import time
from .rpc import decode, first, integer

EDITOR_MARKER = b'REM Editor text entry only; no RUN or SAVE.\n'
TARGET_MARKER = b'REM FLIPPER2JB TARGET NS2JB; fresh session only\n'


def duration(data):
    if not data.startswith((EDITOR_MARKER, TARGET_MARKER)):
        return None
    milliseconds, held = 0, set()
    for line in data.decode('ascii').splitlines():
        if line.startswith('REM '): continue
        action, _, value = line.partition(' ')
        if action == 'DELAY' and value.isdecimal():
            delay = int(value)
            if not 1 <= delay <= 600000: raise ValueError('invalid generated delay')
            milliseconds += delay
        elif action in ('HOLD', 'RELEASE'):
            if value not in ('SPACE','SHIFT','ENTER','HOME','END','BACKSPACE') and not (len(value)==1 and 33<=ord(value)<=126):
                raise ValueError('unsupported generated key')
            if action == 'HOLD':
                if value in held: raise ValueError('duplicate held key')
                held.add(value)
            else:
                if value not in held: raise ValueError('release without hold')
                held.remove(value)
        else:
            raise ValueError('auto-close requires an unmodified generated script')
    if held or not milliseconds: raise ValueError('incomplete generated script')
    return milliseconds/1000


def enabled_duration(data, preference=None):
    if preference is False: return None
    seconds = duration(data)
    if preference is True and seconds is None:
        raise ValueError('auto-close supports only Flipper2JB-generated scripts')
    return seconds


def is_locked(rpc):
    replies = rpc.request(17, b'')
    for reply in replies:
        if 18 in reply:
            value = first(decode(first(reply,18)),1,0)
            if value in (0,1): return bool(value)
    raise RuntimeError('could not verify Flipper application state')


def header(frame):
    # Packed Flipper framebuffer: first 128 bytes are the top eight pixel rows.
    if len(frame)!=1024 or not any(frame[:128]):
        raise RuntimeError('could not identify the opened script screen')
    return frame[:128]


def prepare(rpc):
    if not is_locked(rpc): raise RuntimeError('Bad KB did not open')
    return header(rpc.screen_frame())


def wait_and_close(rpc, seconds, expected_header):
    if not math.isfinite(seconds) or seconds<=0: raise ValueError('invalid auto-close duration')
    # Parser/USB processing adds overhead to the explicit script DELAY commands.
    buffer = max(10.0, seconds*0.25)
    remaining = seconds+buffer
    print(f'Timed auto-close enabled: waiting {remaining:.1f}s including {buffer:.1f}s buffer. Keep this command running.',flush=True)
    while remaining>0:
        interval = min(5.0,remaining)
        time.sleep(interval); remaining -= interval
        if not is_locked(rpc):
            print('Flipper application already closed; no Back input sent.',flush=True)
            return
        if header(rpc.screen_frame()) != expected_header:
            raise RuntimeError('Flipper screen changed; auto-close cancelled without sending Back')
    # This is a timed exit, not a report of script/USB completion. Never press OK again.
    for event in (0,2,1): rpc.request(23,integer(1,5)+integer(2,event))
    for _ in range(10):
        if not is_locked(rpc):
            print('Flipper application exit verified. The remote script is retained.',flush=True)
            return
        time.sleep(.2)
    raise RuntimeError('application exit not confirmed; no additional Back input sent')
